import React from "react";

const UserDashboard = ({ slots, onAdminLogin }) => {
  const totalSlots = slots.length;
  const occupiedSlots = slots.filter((s) => s.status === "occupied").length;
  const availableSlots = totalSlots - occupiedSlots;

  return (
    <div className="w-full min-h-screen bg-gray-100 p-6">

      {/* Header */}
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold flex items-center gap-2">
          🚗 Parking Dashboard
        </h1>

        <div className="flex items-center gap-4">
          {/* Live updating */}
          <span className="px-4 py-2 bg-green-100 text-green-700 rounded-full text-sm font-medium shadow">
            ● Live Updating
          </span>

          {/* Admin login */}
          <button
            onClick={onAdminLogin}
            className="px-4 py-2 rounded-lg bg-blue-600 text-white font-medium hover:bg-blue-700 shadow"
          >
            Admin Login
          </button>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-3 gap-4 mb-8">
        <div className="bg-blue-50 p-6 rounded-xl shadow border border-blue-100">
          <p className="text-gray-500">Total Slots</p>
          <p className="text-4xl font-bold text-blue-600">{totalSlots}</p>
        </div>

        <div className="bg-green-50 p-6 rounded-xl shadow border border-green-100">
          <p className="text-gray-500">Available Slots</p>
          <p className="text-4xl font-bold text-green-600">{availableSlots}</p>
        </div>

        <div className="bg-red-50 p-6 rounded-xl shadow border border-red-100">
          <p className="text-gray-500">Occupied Slots</p>
          <p className="text-4xl font-bold text-red-600">{occupiedSlots}</p>
        </div>
      </div>

      {/* Section Title */}
      <h2 className="text-xl font-semibold mb-4">Parking Slots</h2>

      {/* Slot Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {slots.map((slot, index) => (
          <div
            key={index}
            className={`p-5 rounded-xl shadow border ${
              slot.status === "occupied"
                ? "bg-red-50 border-red-200"
                : "bg-green-50 border-green-200"
            }`}
          >
            <div className="flex justify-between items-center mb-2">
              <h3 className="font-semibold text-lg">Slot {slot.slot}</h3>

              <span
                className={`px-3 py-1 text-sm rounded-full font-medium ${
                  slot.status === "occupied"
                    ? "bg-red-200 text-red-700"
                    : "bg-green-200 text-green-700"
                }`}
              >
                {slot.status === "occupied" ? "Occupied" : "Vacant"}
              </span>
            </div>

            <div className="text-gray-700 space-y-1">
              <p>
                <strong>Plate:</strong>{" "}
                {slot.plate ? slot.plate : "—"}
              </p>
              <p>
                <strong>Last activity:</strong> {slot.lastActivity}
              </p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default UserDashboard;
